// @ts-check
import next from "@next/eslint-plugin-next";
import eslintConfig from "@purplefish-ai/eslint-config";
// @ts-expect-error
import boundaries from "eslint-plugin-boundaries";
import storybook from "eslint-plugin-storybook";

import noProcessEnv from "./eslint-rules/no-process-env.js";
import noServerEnvInClient from "./eslint-rules/no-server-env-in-client.js";

export default [
  ...eslintConfig,
  ...storybook.configs["flat/recommended"],
  {
    ignores: [
      "eslint-rules/no-process-env.js",
      "eslint-rules/no-server-env-in-client.js",
      // Storybook build output
      "storybook-static/**",
      "test_scripts/**/*",
      "next-env.d.ts",
    ],
  },
  {
    plugins: {
      boundaries,
      "@next/next": next,
      custom: {
        rules: {
          "no-process-env": noProcessEnv,
          "no-server-env-in-client": noServerEnvInClient,
        },
      },
    },
    rules: {
      "custom/no-process-env": [
        "error",
        {
          excludeFiles: ["env.ts", "next.config.ts"],
        },
      ],
      "custom/no-server-env-in-client": "error",
      ...boundaries.configs.recommended.rules,
      ...next.configs.recommended.rules,
      // The goal is to turn these on, but they have a lot of errors!
      "@typescript-eslint/no-unsafe-assignment": "off",
      "@typescript-eslint/no-unsafe-return": "off",
      "@typescript-eslint/no-unsafe-call": "off",
      "@typescript-eslint/no-unsafe-member-access": "off",
      "@typescript-eslint/no-unsafe-argument": "off",
      "@typescript-eslint/require-await": "off",
      "@typescript-eslint/no-unnecessary-condition": "off",
      "@typescript-eslint/no-unnecessary-type-assertion": "off",
      "@typescript-eslint/strict-boolean-expressions": [
        "warn",
        {
          allowNullableBoolean: true,
          allowNullableString: true,
          allowNullableObject: true,
        },
      ],
      "@typescript-eslint/no-misused-promises": [
        2,
        {
          checksVoidReturn: {
            attributes: false,
          },
        },
      ],
      "boundaries/no-unknown-files": "error",
      "boundaries/element-types": [
        2,
        {
          default: "disallow",
          rules: [
            {
              from: "app",
              allow: [
                "app",
                "components",
                "auth",
                "server",
                "common",
                "styles",
                "env",
                "types",
                "emailTemplates",
                "contexts",
              ],
            },
            {
              from: "api",
              allow: ["api", "server", "services", "common", "env", "types"],
            },
            {
              from: "middleware",
              allow: ["middleware", "env", "auth"],
            },
            {
              from: "auth",
              allow: ["auth", "env", "server"],
            },
            {
              from: "components",
              allow: ["components", "common", "auth", "server", "contexts"],
            },
            {
              from: "server",
              allow: [
                "server",
                "auth",
                "components",
                "app",
                "common",
                "env",
                "emailTemplates",
                "integrations",
              ],
            },
            {
              from: "emailTemplates",
              allow: ["emailTemplates", "server", "common", "env", "models"],
            },
            {
              from: "common",
              allow: ["common", "server", "env", "models"],
            },
            {
              from: "integrations",
              allow: ["integrations", "server", "common", "env", "auth"],
            },
          ],
        },
      ],
      "no-implicit-coercion": [
        "error",
        {
          boolean: true,
          number: true,
          string: true,
        },
      ],
      "import/no-duplicates": "error",
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              group: ["next/navigation"],
              importNames: ["useRouter"],
              message: "Use 'useRouter' from @bprogress/next/app instead.",
            },
            {
              group: ["lucide-react"],
              message: "Use icons from @purplefish-ai/material-icons instead.",
            },
          ],
        },
      ],
    },
    settings: {
      "boundaries/ignore": ["!src/**/*", "**/messaging-agents-client/**"],
      "boundaries/elements": [
        {
          type: "app",
          pattern: ["src/app/!(*api)/**/*.{ts,tsx}", "src/app/*.{ts,tsx}"],
          mode: "full",
        },
        {
          type: "api",
          pattern: "src/app/api/**/*.{ts,tsx}",
          mode: "full",
        },
        {
          type: "components",
          pattern: "src/components/**/*.{ts,tsx}",
          mode: "full",
        },
        {
          type: "contexts",
          pattern: "src/contexts/**/*.{ts,tsx}",
          mode: "full",
        },
        {
          type: "trpc",
          pattern: "src/trpc/**/*.{ts,tsx}",
          mode: "full",
        },
        {
          type: "server",
          pattern: "src/server/**/*.{ts,tsx}",
          mode: "full",
        },
        {
          type: "common",
          pattern: "src/common/**/*.{ts,tsx}",
          mode: "full",
        },
        {
          type: "auth",
          pattern: "src/auth.ts",
          mode: "file",
        },
        {
          type: "env",
          pattern: "src/env.ts",
          mode: "file",
        },
        {
          type: "instrumentation",
          pattern: "src/instrumentation.ts",
          mode: "file",
        },
        {
          type: "styles",
          pattern: "src/styles/**/*.css",
          mode: "full",
        },
        {
          type: "emailTemplates",
          pattern: "src/emails/**/*.{ts,tsx}",
          mode: "full",
