// @ts-nocheck
export default {
  meta: {
    type: "problem",
    docs: {
      description: "Disallow Prisma queries with both select and include",
    },
    schema: [],
  },
  create(context) {
    return {
      ObjectExpression(node) {
        if (
          node.properties.some((prop) => prop.key?.name === "select") &&
          node.properties.some((prop) => prop.key?.name === "include")
        ) {
          context.report({
            message:
              "Do not use `select` and `include` in the same Prisma query.",
            loc: node.loc,
          });
        }
      },
    };
  },
};

