// Test file for Prisma rule
import { prisma } from "@/server/db";

async function testQueries() {
  // This should trigger the rule - using both select and include
  const badQuery = await prisma.user.findMany({
    where: { id: 1 },
    select: {
      id: true,
      name: true,
    },
    include: {
      posts: true,
    },
  });

  // This should be fine - only select
  const goodQuery1 = await prisma.user.findMany({
    where: { id: 1 },
    select: {
      id: true,
      name: true,
    },
  });

  // This should be fine - only include
  const goodQuery2 = await prisma.user.findMany({
    where: { id: 1 },
    include: {
      posts: true,
    },
  });

  // Another bad example with different order
  const badQuery2 = await prisma.post.findFirst({
    include: {
      author: true,
    },
    select: {
      title: true,
      content: true,
    },
    where: {
      published: true,
    },
  });
}

